changeSet.createProcedure:
CREATE FUNCTION public.admit_team_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.team_item_version v
        WHERE v.id = NEW.version_id AND v.workspace_id = NEW.workspace_id AND v.state = 'AVAILABLE'
        AND v.created_in_transaction = pg_current_xact_id()::text::bigint
        FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a snapshot arrives only with its new team item version' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

CREATE FUNCTION public.delete_ended_team_version_content() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM public.team_snapshot s WHERE s.version_id = NEW.id AND s.workspace_id = NEW.workspace_id;
    RETURN NULL;
END $$

changeSet.sql:
CREATE TRIGGER team_snapshot_admit BEFORE INSERT ON public.team_snapshot
    FOR EACH ROW EXECUTE FUNCTION public.admit_team_snapshot();
CREATE TRIGGER team_snapshot_guard AFTER UPDATE ON public.team_snapshot
    FOR EACH ROW EXECUTE FUNCTION public.guard_team_snapshot();

changeSet.rollback:
DROP TRIGGER team_snapshot_guard ON public.team_snapshot;
DROP TRIGGER team_snapshot_admit ON public.team_snapshot;
DROP FUNCTION public.delete_ended_team_version_content();
DROP FUNCTION public.guard_team_snapshot();
DROP FUNCTION public.admit_team_snapshot();
